/**
 * @name XML External Entity (XXE) vulnerability
 * @description Using unsafe XML parsers that allow external entity expansion can lead to XXE attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/xxe
 * @tags security
 *        external/cwe/cwe-611
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module XxeConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // XML parsing operations that could be vulnerable to XXE
    exists(DataFlow::CallCfgNode call |
      // lxml library
      call = API::moduleImport("lxml").getMember("parse").getACall() or
      call = API::moduleImport("lxml").getMember("fromstring").getACall() or
      call = API::moduleImport("lxml").getMember("XMLParser").getACall() or
      // xml.etree.ElementTree library
      call = API::moduleImport("xml").getMember("etree").getMember("ElementTree").getMember("parse").getACall() or
      call = API::moduleImport("xml").getMember("etree").getMember("ElementTree").getMember("fromstring").getACall() or
      // xml.dom.minidom
      call = API::moduleImport("xml").getMember("dom").getMember("minidom").getMember("parse").getACall() or
      call = API::moduleImport("xml").getMember("dom").getMember("minidom").getMember("parseString").getACall() or
      // xml.sax
      call = API::moduleImport("xml").getMember("sax").getMember("parse").getACall() or
      call = API::moduleImport("xml").getMember("sax").getMember("parseString").getACall()
    |
      // Get the first argument (usually the XML data/source)
      sink = call.getArg(0)
    )
  }
}

module XxeFlow = TaintTracking::Global<XxeConfig>;
import XxeFlow::PathGraph

from XxeFlow::PathNode source, XxeFlow::PathNode sink
where XxeFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "XML External Entity (XXE) vulnerability from $@.", source.getNode(), "user input"

/**
 * @name Path traversal vulnerability
 * @description Using user input in file operations without proper validation can lead to path traversal attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal
 * @tags security
 *        external/cwe/cwe-22
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // File operations that could be vulnerable to path traversal
    exists(DataFlow::CallCfgNode call |
      // open() function
      call = API::builtin("open").getACall() or
      // file() function (Python 2 compatibility)
      call = API::builtin("file").getACall() or
      // os.path operations
      call = API::moduleImport("os").getMember("path").getMember("join").getACall() or
      call = API::moduleImport("os").getMember("path").getMember("abspath").getACall() or
      call = API::moduleImport("os").getMember("path").getMember("realpath").getACall() or
      // os module file operations
      call = API::moduleImport("os").getMember("open").getACall() or
      call = API::moduleImport("os").getMember("chdir").getACall() or
      call = API::moduleImport("os").getMember("remove").getACall() or
      call = API::moduleImport("os").getMember("rename").getACall() or
      call = API::moduleImport("os").getMember("stat").getACall() or
      // built-in file operations
      call = API::moduleImport("builtins").getMember("open").getACall()
    |
      // Get the first argument (usually the file path)
      sink = call.getArg(0)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal vulnerability from $@.", source.getNode(), "user input"

/**
 * @name Cross-Site Scripting (XSS) vulnerability
 * @description Unsanitized user input in HTML output can lead to XSS attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/xss
 * @tags security
 *        external/cwe/cwe-079
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module XssConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // HTML output operations
    exists(DataFlow::CallCfgNode call |
      // Beautiful Soup operations that output HTML
      call = API::moduleImport("bs4").getMember("BeautifulSoup").getACall() or
      call = API::moduleImport("bs4").getMember("Tag").getMember(["append", "insert", "extend", "wrap", "unwrap"]).getACall() or
      call = API::moduleImport("bs4").getMember("Tag").getMember("replace_with").getACall() or
      // String operations that could output HTML
      call = API::builtin("str").getMember("format").getACall() or
      call = API::builtin("str").getMember("replace").getACall() or
      call = API::builtin("str").getMember("join").getACall()
    |
      sink = call.getArg(0)
    )
  }
}

module XssFlow = TaintTracking::Global<XssConfig>;
import XssFlow::PathGraph

from XssFlow::PathNode source, XssFlow::PathNode sink
where XssFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Cross-Site Scripting (XSS) vulnerability from $@.", source.getNode(), "user input"

/**
 * @name Regular Expression Injection (ReDoS)
 * @description Using user-controlled input in regular expressions can lead to ReDoS attacks
 * @kind path-problem
 * @problem.severity warning
 * @id py/redos
 * @tags security
 *        external/cwe/cwe-1333
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module ReDoSConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Regular expression compilation or matching operations
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("re").getMember(["compile", "search", "match", "findall", "finditer", "sub", "subn", "split"]).getACall() or
      call = API::builtin("compile").getACall() and call.getArg(0).asExpr().toString() = "re"
    |
      // Get the pattern argument (usually first argument)
      sink = call.getArg(0)
    )
  }
}

module ReDoSFlow = TaintTracking::Global<ReDoSConfig>;
import ReDoSFlow::PathGraph

from ReDoSFlow::PathNode source, ReDoSFlow::PathNode sink
where ReDoSFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Regular expression injection (ReDoS) vulnerability from $@.", source.getNode(), "user input"
